<?php
require_once __DIR__.'/../includes/admin_layout.php'; $file=__DIR__.'/../data/inventory.json'; $rows=readJson($file); $edit=null;$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??'';$id=(int)($_POST['id']??0); if($action==='delete'){ $rows=array_values(array_filter($rows,fn($r)=>(int)$r['id']!==$id));writeJson($file,$rows);$msg='Inventory item deleted.';} elseif($action==='save'){ $name=trim($_POST['name']??'');$qty=(int)($_POST['quantity']??0);$unit=trim($_POST['unit']??'');$min=(int)($_POST['minimum']??0);if(!$name||!$unit||$qty<0||$min<0)$error='Enter valid inventory details.';else{if($id){foreach($rows as &$r)if((int)$r['id']===$id){$r=['id'=>$id,'name'=>$name,'quantity'=>$qty,'unit'=>$unit,'minimum'=>$min];break;}unset($r);}else{$rows[]=['id'=>nextId($rows),'name'=>$name,'quantity'=>$qty,'unit'=>$unit,'minimum'=>$min];}writeJson($file,$rows);header('Location: inventory.php?msg=saved');exit;}}} if(isset($_GET['edit']))foreach($rows as $r)if((int)$r['id']===(int)$_GET['edit'])$edit=$r;if(isset($_GET['msg']))$msg='Inventory saved successfully.'; adminStart('Inventory','inventory'); if($msg):?><div class="notice success">✅ <?=h($msg)?></div><?php endif;?><?php if($error):?><div class="notice error">❌ <?=h($error)?></div><?php endif;?><div class="admin-two"><section class="admin-panel"><h2><?= $edit?'✏️ Edit Item':'➕ Add Inventory Item'?></h2><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($edit['id']??0)?>"><div class="form-group"><label>Name</label><input class="form-control" name="name" required value="<?=h($edit['name']??'')?>"></div><div class="form-group"><label>Quantity</label><input class="form-control" type="number" min="0" name="quantity" required value="<?=h($edit['quantity']??0)?>"></div><div class="form-group"><label>Unit</label><input class="form-control" name="unit" required value="<?=h($edit['unit']??'pieces')?>"></div><div class="form-group"><label>Minimum Level</label><input class="form-control" type="number" min="0" name="minimum" required value="<?=h($edit['minimum']??0)?>"></div><button class="btn btn-primary">💾 Save</button> <?php if($edit):?><a class="btn btn-secondary" href="inventory.php">Cancel</a><?php endif;?></form></section><section class="admin-panel"><h2>📋 Stock List</h2><div class="table-wrap"><table><tr><th>Item</th><th>Qty</th><th>Minimum</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):$low=(int)$r['quantity']<=(int)$r['minimum'];?><tr><td><?=h($r['name'])?></td><td><?=h($r['quantity'])?> <?=h($r['unit'])?></td><td><?=h($r['minimum'])?></td><td><?=$low?'⚠️ Low':'🟢 Good'?></td><td><a class="btn btn-secondary" href="inventory.php?edit=<?=$r['id']?>">Edit</a> <form method="post" style="display:inline"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-danger" onclick="return confirm('Delete item?')">Delete</button></form></td></tr><?php endforeach;?></table></div></section></div><?php adminEnd();?>